    assert_eq!(checker.check_expression(&expr), Ok(Type::String));
}

#[test]
fn test_type_boolean_literal() {
    let mut checker = TypeChecker::new();
    let expr = Expression::Literal(Literal::Boolean(true));
    assert_eq!(checker.check_expression(&expr), Ok(Type::Boolean));
}

