fn test_type_arithmetic_floats() {
    let mut checker = TypeChecker::new();
    let expr = Expression::BinaryOp {
        op: "Slash".to_string(),
        left: Box::new(Expression::Literal(Literal::Float(10.0))),
        right: Box::new(Expression::Literal(Literal::Float(2.5))),
    };
    assert_eq!(checker.check_expression(&expr), Ok(Type::Float));
}

#[test]
fn test_type_arithmetic_mixed_numeric() {
    let mut checker = TypeChecker::new();
    let expr = Expression::BinaryOp {
        op: "Plus".to_string(),
        left: Box::new(Expression::Literal(Literal::Integer(1))),
        right: Box::new(Expression::Literal(Literal::Float(2.5))),
    };
    // i32 + f64 → f64
    assert_eq!(checker.check_expression(&expr), Ok(Type::Float));
