#[test]
fn test_function_signature_basic() {
    let mut checker = TypeChecker::new();
    let program = Program {
        definitions: vec![Definition::Function {
            name: "add".to_string(),
            params: vec!["x".to_string(), "y".to_string()],
            body: vec![],
        }],
    };

    let result = checker.check(&program);
    assert!(result.is_ok());

    // 함수 시그니처 확인
    let sig = checker.get_function_signature("add");
    assert!(sig.is_some());
    assert_eq!(sig.unwrap().name, "add");
    assert_eq!(sig.unwrap().params.len(), 2);
}

