#[test]
fn test_scope_variable_definition() {
    let mut checker = TypeChecker::new();
    let stmt = Statement::LetBinding {
        name: "x".to_string(),
        value: Box::new(Expression::Literal(Literal::Integer(10))),
    };

    let result = checker.check_statement(&stmt);
    assert!(result.is_ok());
    assert_eq!(result.unwrap(), Type::Integer);
}

#[test]
fn test_scope_duplicate_definition() {
    let mut checker = TypeChecker::new();
    let stmt1 = Statement::LetBinding {
        name: "x".to_string(),
        value: Box::new(Expression::Literal(Literal::Integer(10))),
    };

    let stmt2 = Statement::LetBinding {
        name: "x".to_string(),
        value: Box::new(Expression::Literal(Literal::Float(3.14))),
    };

    let result1 = checker.check_statement(&stmt1);
    assert!(result1.is_ok());

    let result2 = checker.check_statement(&stmt2);
    assert!(result2.is_err());
    assert!(result2.unwrap_err().message.contains("중복된 변수"));
}

#[test]
fn test_scope_variable_shadowing() {
    let mut checker = TypeChecker::new();

    // 외부 스코프에 x 정의
    let stmt1 = Statement::LetBinding {
        name: "x".to_string(),
        value: Box::new(Expression::Literal(Literal::Integer(10))),
    };
    checker.check_statement(&stmt1).ok();

    // 내부 스코프 진입
    checker.symbol_table.enter_scope();

    // 내부 스코프에서 x 재정의 (shadowing)
    let stmt2 = Statement::LetBinding {
        name: "x".to_string(),
        value: Box::new(Expression::Literal(Literal::String("hello".to_string()))),
    };
    let result = checker.check_statement(&stmt2);
    assert!(result.is_ok());
    assert_eq!(result.unwrap(), Type::String);

    // 내부 스코프 종료
    checker.symbol_table.exit_scope();

    // 외부 스코프에서 조회하면 정수형 x
    let x_type = checker.symbol_table.get_type("x");
    assert_eq!(x_type, Some(Type::Integer));
}

#[test]
fn test_scope_depth_tracking() {
    let mut checker = TypeChecker::new();
    assert_eq!(checker.current_scope_depth(), 0);

    checker.symbol_table.enter_scope();
    assert_eq!(checker.current_scope_depth(), 1);

    checker.symbol_table.enter_scope();
    assert_eq!(checker.current_scope_depth(), 2);

    checker.symbol_table.exit_scope();
    assert_eq!(checker.current_scope_depth(), 1);

    checker.symbol_table.exit_scope();
    assert_eq!(checker.current_scope_depth(), 0);
}

