#[test]
fn test_scope_variable_access_outside_scope() {
    let mut checker = TypeChecker::new();

    checker.symbol_table.enter_scope();
    let stmt = Statement::LetBinding {
        name: "temp".to_string(),
        value: Box::new(Expression::Literal(Literal::Integer(42))),
    };
    checker.check_statement(&stmt).ok();
    checker.symbol_table.exit_scope();

    // temp는 현재 스코프에서 접근 불가
    let accessible = checker.is_variable_accessible("temp");
    assert!(!accessible);
}

#[test]
fn test_scope_nested_blocks() {
    let mut checker = TypeChecker::new();

    // Level 0 (global)
    let stmt1 = Statement::LetBinding {
        name: "global_var".to_string(),
        value: Box::new(Expression::Literal(Literal::Integer(100))),
    };
    checker.check_statement(&stmt1).ok();

    // Level 1
    checker.symbol_table.enter_scope();
    let stmt2 = Statement::LetBinding {
        name: "level1_var".to_string(),
        value: Box::new(Expression::Literal(Literal::String("L1".to_string()))),
    };
    checker.check_statement(&stmt2).ok();

    // Level 2
    checker.symbol_table.enter_scope();
    let stmt3 = Statement::LetBinding {
        name: "level2_var".to_string(),
        value: Box::new(Expression::Literal(Literal::Float(2.71))),
    };
    checker.check_statement(&stmt3).ok();

    // Level 2에서는 모든 변수 접근 가능
    assert!(checker.is_variable_accessible("global_var"));
    assert!(checker.is_variable_accessible("level1_var"));
    assert!(checker.is_variable_accessible("level2_var"));

    checker.symbol_table.exit_scope();

    // Level 1에서는 level2_var 접근 불가
    assert!(checker.is_variable_accessible("global_var"));
    assert!(checker.is_variable_accessible("level1_var"));
    assert!(!checker.is_variable_accessible("level2_var"));

    checker.symbol_table.exit_scope();

    // Level 0에서는 level1_var, level2_var 접근 불가
    assert!(checker.is_variable_accessible("global_var"));
    assert!(!checker.is_variable_accessible("level1_var"));
    assert!(!checker.is_variable_accessible("level2_var"));
}

#[test]
fn test_scope_current_scope_variables() {
    let mut checker = TypeChecker::new();

    let stmt1 = Statement::LetBinding {
        name: "a".to_string(),
        value: Box::new(Expression::Literal(Literal::Integer(1))),
    };
    let stmt2 = Statement::LetBinding {
        name: "b".to_string(),
        value: Box::new(Expression::Literal(Literal::String("b".to_string()))),
    };

    checker.check_statement(&stmt1).ok();
    checker.check_statement(&stmt2).ok();

    let vars = checker.current_scope_variables();
    assert_eq!(vars.len(), 2);
    assert!(vars.iter().any(|(n, _)| n == "a"));
    assert!(vars.iter().any(|(n, _)| n == "b"));
}

#[test]
fn test_scope_variable_lifetime() {
    let mut checker = TypeChecker::new();

    // 전역 변수 정의
    let global = Statement::LetBinding {
        name: "x".to_string(),
        value: Box::new(Expression::Literal(Literal::Integer(10))),
    };
    checker.check_statement(&global).ok();

    // 블록 진입
    checker.symbol_table.enter_scope();

    // 블록 변수 정의
    let local = Statement::LetBinding {
        name: "y".to_string(),
        value: Box::new(Expression::Literal(Literal::Integer(20))),
    };
    checker.check_statement(&local).ok();

    // 블록 내에서 모두 접근 가능
    assert_eq!(checker.current_scope_variables().len(), 1); // y만 현재 스코프
    assert!(checker.is_variable_accessible("x"));
    assert!(checker.is_variable_accessible("y"));

    // 블록 종료
    checker.symbol_table.exit_scope();

    // 블록 종료 후 y는 접근 불가
    assert!(checker.is_variable_accessible("x"));
    assert!(!checker.is_variable_accessible("y"));
}

#[test]
fn test_scope_multiple_shadowing() {
    let mut checker = TypeChecker::new();

    // 전역: x = i32
    let stmt1 = Statement::LetBinding {
        name: "x".to_string(),
        value: Box::new(Expression::Literal(Literal::Integer(1))),
    };
    checker.check_statement(&stmt1).ok();

    // Level 1: x = String (shadow)
    checker.symbol_table.enter_scope();
    let stmt2 = Statement::LetBinding {
        name: "x".to_string(),
        value: Box::new(Expression::Literal(Literal::String("L1".to_string()))),
    };
    checker.check_statement(&stmt2).ok();
    assert_eq!(checker.symbol_table.get_type("x"), Some(Type::String));

    // Level 2: x = float (re-shadow)
    checker.symbol_table.enter_scope();
    let stmt3 = Statement::LetBinding {
        name: "x".to_string(),
        value: Box::new(Expression::Literal(Literal::Float(3.14))),
    };
    checker.check_statement(&stmt3).ok();
    assert_eq!(checker.symbol_table.get_type("x"), Some(Type::Float));

    checker.symbol_table.exit_scope();
    assert_eq!(checker.symbol_table.get_type("x"), Some(Type::String));

    checker.symbol_table.exit_scope();
    assert_eq!(checker.symbol_table.get_type("x"), Some(Type::Integer));
}

#[test]
fn test_scope_function_parameter_scope() {
    let mut checker = TypeChecker::new();
    let program = Program {
