    assert!(result.is_ok());
}

#[test]
fn test_scope_variable_type_consistency() {
    let mut checker = TypeChecker::new();

    // x를 정의
    let stmt1 = Statement::LetBinding {
        name: "x".to_string(),
        value: Box::new(Expression::Literal(Literal::Integer(10))),
    };
    checker.check_statement(&stmt1).ok();

    // x를 사용할 때 타입이 일치하는지 확인
    let var_expr = Expression::Variable("x".to_string());
    let var_type = checker.check_expression(&var_expr);
    assert_eq!(var_type, Ok(Type::Integer));
}

