    fn check_binary_op(
        &self,
        op: &str,
        left_type: &Type,
        right_type: &Type,
    ) -> Result<Type, TypeError> {
        match op {
            // 산술 연산자
            "Plus" | "Minus" | "Star" | "Slash" | "Percent" => {
                if left_type.is_numeric() && right_type.is_numeric() {
                    // 결과 타입은 더 넓은 타입
                    match (left_type, right_type) {
                        (Type::Float, _) | (_, Type::Float) => Ok(Type::Float),
                        _ => Ok(left_type.clone()),
                    }
                } else if left_type == Type::Unknown || right_type == Type::Unknown {
                    Ok(Type::Unknown)
                } else {
                    Err(TypeError::new(format!(
                        "산술 연산 '{}'은 숫자 타입이어야 하지만 {} 과 {} 을(를) 받음",
                        op, left_type, right_type
                    )))
                }
            }
            // 비교 연산자
            "Eq" | "Ne" | "Lt" | "Le" | "Gt" | "Ge" => {
                if left_type.is_compatible(right_type) {
                    Ok(Type::Boolean)
                } else if left_type == Type::Unknown || right_type == Type::Unknown {
                    Ok(Type::Boolean)
                } else {
                    Err(TypeError::new(format!(
                        "비교 연산 '{}'에서 호환되지 않는 타입: {} 과 {}",
                        op, left_type, right_type
                    )))
                }
            }
            // 논리 연산자
            "And" | "Or" => {
                if left_type == Type::Boolean && right_type == Type::Boolean {
                    Ok(Type::Boolean)
                } else if left_type == Type::Unknown || right_type == Type::Unknown {
                    Ok(Type::Boolean)
                } else {
                    Err(TypeError::new(format!(
                        "논리 연산 '{}'은 bool 타입이어야 하지만 {} 과 {} 을(를) 받음",
                        op, left_type, right_type
                    )))
                }
            }
            _ => Err(TypeError::new(format!("알 수 없는 연산자: '{}'", op))),
        }
    }

    /// 단항 연산을 타입 검사합니다
    fn check_unary_op(&self, op: &str, operand_type: &Type) -> Result<Type, TypeError> {
        match op {
            "Not" => {
                if operand_type == Type::Boolean || operand_type == Type::Unknown {
                    Ok(Type::Boolean)
                } else {
                    Err(TypeError::new(format!(
                        "! 연산은 bool 타입이어야 하지만 {} 을(를) 받음",
                        operand_type
                    )))
                }
            }
            "Minus" => {
                if operand_type.is_numeric() || operand_type == Type::Unknown {
                    Ok(operand_type.clone())
                } else {
                    Err(TypeError::new(format!(
                        "- 연산은 숫자 타입이어야 하지만 {} 을(를) 받음",
                        operand_type
                    )))
                }
            }
            _ => Err(TypeError::new(format!("알 수 없는 단항 연산자: '{}'", op))),
        }
    }

    /// 모든 타입 검사 에러를 반환합니다
    pub fn get_errors(&self) -> &[TypeError] {
        &self.errors
    }

    /// 심볼 테이블의 현재 심볼들을 반환합니다
    pub fn current_symbols(&self) -> Vec<(String, Type)> {
        self.symbol_table
            .current_symbols()
            .into_iter()
            .map(|s| (s.name, s.type_))
            .collect()
    }

    /// 함수 시그니처를 조회합니다
    pub fn get_function_signature(&self, name: &str) -> Option<FunctionSignature> {
        self.function_signatures.get(name).cloned()
    }

    /// 모든 함수 시그니처를 반환합니다
    pub fn all_function_signatures(&self) -> Vec<FunctionSignature> {
        self.function_signatures.values().cloned().collect()
    }

    /// 현재 스코프 깊이를 반환합니다
    pub fn current_scope_depth(&self) -> usize {
        self.symbol_table.current_scope_level()
    }

    /// 변수가 현재 스코프에서 접근 가능한지 확인합니다
    pub fn is_variable_accessible(&self, name: &str) -> bool {
        self.symbol_table.lookup(name).is_some()
    }

    /// 현재 스코프의 모든 변수를 반환합니다
    pub fn current_scope_variables(&self) -> Vec<(String, Type)> {
        self.symbol_table
            .current_symbols()
            .into_iter()
            .map(|s| (s.name, s.type_))
            .collect()
    }
}

