        Expression::Match { .. } => {
            // 향후 match 표현식 구현
            Ok(Type::Unknown)
        }
        Expression::Array { elements } => {
            if elements.is_empty() {
                // 빈 배열은 Unknown 타입
                Ok(Type::Array {
                    element_type: Box::new(Type::Unknown),
                })
            } else {
                // 첫 번째 요소의 타입을 기준으로 함
                let first_type = self.check_expression(&elements[0])?;

                // 모든 요소가 같은 타입인지 확인
                for (i, elem) in elements.iter().enumerate().skip(1) {
                    let elem_type = self.check_expression(elem)?;
                    if !elem_type.is_compatible(&first_type) {
                        return Err(TypeError::new(format!(
                            "배열 요소 {}: 타입 불일치 (기대: {}, 받음: {})",
                            i, first_type, elem_type
                        )));
                    }
                }

                Ok(Type::Array {
                    element_type: Box::new(first_type),
                })
            }
        }
        Expression::Index { expr, index } => {
            let expr_type = self.check_expression(expr)?;
            let index_type = self.check_expression(index)?;

            // 인덱스는 정수여야 함
            if index_type != Type::Integer && index_type != Type::Unknown {
                return Err(TypeError::new(format!(
                    "배열 인덱스는 정수여야 하지만 {}을(를) 받음",
                    index_type
                )));
            }

            // 배열 타입이어야 함
            match expr_type {
                Type::Array { element_type } => Ok(*element_type),
                Type::Unknown => Ok(Type::Unknown),
                _ => Err(TypeError::new(format!(
                    "배열 인덱싱은 배열 타입에만 가능하지만 {}을(를) 받음",
                    expr_type
                ))),
            }
        }
        Expression::Tuple { elements } => {
            let mut tuple_types = Vec::new();

            for elem in elements {
                let elem_type = self.check_expression(elem)?;
                tuple_types.push(elem_type);
            }

            Ok(Type::Tuple { types: tuple_types })
        }
    }
}

