// 타입 시스템 정의
// Phase 3: 타입 검사 및 의미 분석

use std::fmt;

/// FV-Lang의 모든 타입을 나타냅니다.
#[derive(Debug, Clone, PartialEq)]
pub enum Type {
    /// 32비트 정수
    Integer,

    /// 64비트 실수
    Float,

    /// 문자열
    String,

    /// 불린
    Boolean,

    /// 함수 타입 (향후)
    Function {
        params: Vec<Type>,
        return_type: Box<Type>,
    },

    /// 배열 타입 (향후)
    Array {
        element_type: Box<Type>,
    },

    /// 튜플 타입 (향후)
    Tuple {
        types: Vec<Type>,
    },

    /// 타입 미결정 (타입 검사 전)
    Unknown,
}

impl Type {
    /// 이 타입이 숫자 타입인지 확인합니다
    pub fn is_numeric(&self) -> bool {
        matches!(self, Type::Integer | Type::Float)
    }

    /// 이 타입이 기본 타입인지 확인합니다
    pub fn is_primitive(&self) -> bool {
        matches!(
            self,
            Type::Integer | Type::Float | Type::String | Type::Boolean
        )
    }

    /// 다른 타입과의 호환성을 확인합니다
    pub fn is_compatible(&self, other: &Type) -> bool {
        match (self, other) {
            // 같은 타입은 호환
            (a, b) if a == b => true,

            // 숫자 타입끼리는 호환 (i32 ↔ f64)
            (Type::Integer, Type::Float) | (Type::Float, Type::Integer) => true,

            // Unknown은 모든 타입과 호환
            (Type::Unknown, _) | (_, Type::Unknown) => true,

            _ => false,
        }
    }

    /// 두 타입의 통합된 타입을 반환합니다 (향후)
    pub fn unify(&self, other: &Type) -> Option<Type> {
        match (self, other) {
            (a, b) if a == b => Some(a.clone()),
            (Type::Integer, Type::Float) | (Type::Float, Type::Integer) => {
                Some(Type::Float)
            }
            (Type::Unknown, t) | (t, Type::Unknown) => Some(t.clone()),
            _ => None,
        }
    }
}

impl fmt::Display for Type {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Type::Integer => write!(f, "i32"),
            Type::Float => write!(f, "f64"),
            Type::String => write!(f, "String"),
            Type::Boolean => write!(f, "bool"),
            Type::Function { params, return_type } => {
                write!(f, "fn(")?;
                for (i, param) in params.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", param)?;
                }
                write!(f, ") -> {}", return_type)
            }
            Type::Array { element_type } => {
                write!(f, "[{}]", element_type)
            }
            Type::Tuple { types } => {
                write!(f, "(")?;
                for (i, t) in types.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", t)?;
                }
                write!(f, ")")
            }
            Type::Unknown => write!(f, "?"),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_type_is_numeric() {
        assert!(Type::Integer.is_numeric());
        assert!(Type::Float.is_numeric());
        assert!(!Type::String.is_numeric());
        assert!(!Type::Boolean.is_numeric());
    }

    #[test]
    fn test_type_is_primitive() {
        assert!(Type::Integer.is_primitive());
        assert!(Type::Float.is_primitive());
        assert!(Type::String.is_primitive());
        assert!(Type::Boolean.is_primitive());
        assert!(!Type::Unknown.is_primitive());
    }

    #[test]
    fn test_type_compatibility_same() {
        assert!(Type::Integer.is_compatible(&Type::Integer));
        assert!(Type::String.is_compatible(&Type::String));
    }

    #[test]
    fn test_type_compatibility_numeric() {
        assert!(Type::Integer.is_compatible(&Type::Float));
        assert!(Type::Float.is_compatible(&Type::Integer));
    }

    #[test]
    fn test_type_compatibility_unknown() {
        assert!(Type::Unknown.is_compatible(&Type::Integer));
        assert!(Type::Integer.is_compatible(&Type::Unknown));
    }

    #[test]
    fn test_type_compatibility_incompatible() {
        assert!(!Type::Integer.is_compatible(&Type::String));
        assert!(!Type::String.is_compatible(&Type::Boolean));
    }

    #[test]
    fn test_type_unify_same() {
        assert_eq!(
            Type::Integer.unify(&Type::Integer),
            Some(Type::Integer)
        );
    }

    #[test]
    fn test_type_unify_numeric() {
        assert_eq!(
            Type::Integer.unify(&Type::Float),
            Some(Type::Float)
        );
    }

    #[test]
    fn test_type_unify_unknown() {
        assert_eq!(
            Type::Unknown.unify(&Type::Integer),
            Some(Type::Integer)
        );
    }

    #[test]
    fn test_type_unify_incompatible() {
        assert_eq!(
            Type::Integer.unify(&Type::String),
            None
        );
    }

    #[test]
    fn test_type_display() {
        assert_eq!(Type::Integer.to_string(), "i32");
        assert_eq!(Type::Float.to_string(), "f64");
        assert_eq!(Type::String.to_string(), "String");
        assert_eq!(Type::Boolean.to_string(), "bool");
        assert_eq!(Type::Unknown.to_string(), "?");
    }
}

