#[test]
fn test_integration_shadowing_with_array() {
    let mut checker = TypeChecker::new();

    let stmt1 = Statement::LetBinding {
        name: "data".to_string(),
        value: Box::new(Expression::Array {
            elements: vec![
                Expression::Literal(Literal::Integer(1)),
                Expression::Literal(Literal::Integer(2)),
            ],
        }),
    };
    checker.check_statement(&stmt1).ok();

    checker.symbol_table.enter_scope();

    let stmt2 = Statement::LetBinding {
        name: "data".to_string(),
        value: Box::new(Expression::Tuple {
            elements: vec![
                Expression::Literal(Literal::Integer(42)),
                Expression::Literal(Literal::String("shadowed".to_string())),
            ],
        }),
    };
    let result = checker.check_statement(&stmt2);
    assert!(result.is_ok());

    let current_type = checker.symbol_table.get_type("data");
    assert_eq!(
        current_type,
        Some(Type::Tuple {
            types: vec![Type::Integer, Type::String]
        })
    );

    checker.symbol_table.exit_scope();

    let outer_type = checker.symbol_table.get_type("data");
    assert_eq!(
        outer_type,
        Some(Type::Array {
            element_type: Box::new(Type::Integer)
        })
    );
}

