            condition: Box::new(IRNode::BoolLiteral(false)),
            then_block: vec![IRNode::IntLiteral(42)],
            else_block: Some(vec![IRNode::IntLiteral(0)]),
        };

        let folded = if_node.fold_constants();
        assert_eq!(folded, IRNode::IntLiteral(0));
    }

    #[test]
    fn test_ir_unary_op_negation() {
        let expr = IRNode::UnaryOp {
            op: "Minus".to_string(),
            operand: Box::new(IRNode::IntLiteral(5)),
        };

        let folded = expr.fold_constants();
        assert_eq!(folded, IRNode::IntLiteral(-5));
    }

    #[test]
    fn test_ir_unary_op_not() {
        let expr = IRNode::UnaryOp {
            op: "Not".to_string(),
            operand: Box::new(IRNode::BoolLiteral(true)),
        };

        let folded = expr.fold_constants();
        assert_eq!(folded, IRNode::BoolLiteral(false));
    }

    #[test]
    fn test_ir_array_literal() {
        let array = IRNode::Array {
            elements: vec![
                IRNode::IntLiteral(1),
