// 코드 생성기
// Phase 4: 코드 생성 (AST → IR → Code)

use crate::ast::*;
use crate::ir::*;
use crate::types::Type;
use std::collections::HashMap;

/// 코드 생성 에러
#[derive(Debug, Clone)]
pub struct CodeGenError {
    pub message: String,
}

impl CodeGenError {
    pub fn new(message: String) -> Self {
        CodeGenError { message }
    }
}

impl std::fmt::Display for CodeGenError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "코드 생성 에러: {}", self.message)
    }
}

impl std::error::Error for CodeGenError {}

/// 코드 생성기
pub struct CodeGenerator {
    current_label: usize,
    function_map: HashMap<String, IRFunction>,
}

impl CodeGenerator {
    /// 새로운 코드 생성기를 생성합니다
    pub fn new() -> Self {
        CodeGenerator {
            current_label: 0,
            function_map: HashMap::new(),
        }
    }

    /// 프로그램을 IR로 변환합니다
    pub fn ast_to_ir(&mut self, program: &Program) -> Result<IRProgram, CodeGenError> {
        let mut functions = Vec::new();
        let mut main = Vec::new();

        // 함수 정의 먼저 수집
        for definition in &program.definitions {
            match definition {
                Definition::Function { name, params, body } => {
                    // 함수 본문을 IR로 변환
                    let ir_body = body
                        .iter()
                        .map(|stmt| self.statement_to_ir(stmt))
                        .collect::<Result<Vec<_>, _>>()?;

                    let ir_func = IRFunction {
                        name: name.clone(),
                        params: params
                            .iter()
                            .map(|p| (p.clone(), Type::Unknown))
                            .collect(),
                        return_type: Type::Unknown,
                        body: ir_body,
                    };

                    self.function_map.insert(name.clone(), ir_func.clone());
                    functions.push(ir_func);
                }
                Definition::TypeDef { .. } => {
                    // 타입 정의는 현재 처리하지 않음
                }
            }
        }

        Ok(IRProgram {
            functions,
            main,
        })
    }

    /// 문장을 IR로 변환합니다
    pub fn statement_to_ir(&mut self, stmt: &Statement) -> Result<IRNode, CodeGenError> {
        match stmt {
            Statement::LetBinding { name, value } => {
                let value_ir = self.expression_to_ir(value)?;
                Ok(IRNode::Assign {
                    name: name.clone(),
                    value: Box::new(value_ir),
                })
            }
            Statement::Return(expr) => {
                let expr_ir = self.expression_to_ir(expr)?;
                Ok(IRNode::Return(Box::new(expr_ir)))
            }
            Statement::If {
                condition,
                then_branch,
                else_branch,
            } => {
                let condition_ir = self.expression_to_ir(condition)?;
                let then_ir: Vec<_> = then_branch
                    .iter()
                    .map(|stmt| self.statement_to_ir(stmt))
                    .collect::<Result<Vec<_>, _>>()?;

                let else_ir = else_branch
                    .as_ref()
                    .map(|stmts| {
                        stmts
                            .iter()
                            .map(|stmt| self.statement_to_ir(stmt))
                            .collect::<Result<Vec<_>, _>>()
                    })
                    .transpose()?;

                Ok(IRNode::If {
                    condition: Box::new(condition_ir),
                    then_block: then_ir,
                    else_block: else_ir,
                })
            }
            Statement::Expression(expr) => self.expression_to_ir(expr),
        }
    }

    /// 표현식을 IR로 변환합니다
    pub fn expression_to_ir(&mut self, expr: &Expression) -> Result<IRNode, CodeGenError> {
        match expr {
            Expression::Literal(lit) => self.literal_to_ir(lit),
            Expression::Variable(name) => Ok(IRNode::Variable(name.clone())),
            Expression::BinaryOp { op, left, right } => {
                let left_ir = self.expression_to_ir(left)?;
                let right_ir = self.expression_to_ir(right)?;

                Ok(IRNode::BinaryOp {
                    op: op.clone(),
                    left: Box::new(left_ir),
                    right: Box::new(right_ir),
                })
            }
            Expression::UnaryOp { op, operand } => {
                let operand_ir = self.expression_to_ir(operand)?;

                Ok(IRNode::UnaryOp {
                    op: op.clone(),
                    operand: Box::new(operand_ir),
                })
            }
            Expression::FunctionCall { name, args } => {
                let args_ir: Vec<_> = args
                    .iter()
                    .map(|arg| self.expression_to_ir(arg))
                    .collect::<Result<Vec<_>, _>>()?;

                Ok(IRNode::FunctionCall {
                    name: name.clone(),
                    args: args_ir,
                })
            }
            Expression::IfExpr {
                condition,
                then_expr,
                else_expr,
            } => {
                let condition_ir = self.expression_to_ir(condition)?;
                let then_ir = self.expression_to_ir(then_expr)?;
                let else_ir = else_expr
                    .as_ref()
                    .map(|e| self.expression_to_ir(e))
                    .transpose()?;

                Ok(IRNode::If {
                    condition: Box::new(condition_ir),
                    then_block: vec![then_ir],
                    else_block: else_ir.map(|e| vec![e]),
                })
            }
            Expression::Match { .. } => {
                // 향후 구현
                Err(CodeGenError::new(
                    "Match 표현식은 아직 구현되지 않았습니다".to_string(),
                ))
            }
            Expression::Array { elements } => {
                let elements_ir: Vec<_> = elements
                    .iter()
                    .map(|e| self.expression_to_ir(e))
                    .collect::<Result<Vec<_>, _>>()?;

                Ok(IRNode::Array {
                    elements: elements_ir,
                })
            }
            Expression::Index { expr, index } => {
                let expr_ir = self.expression_to_ir(expr)?;
                let index_ir = self.expression_to_ir(index)?;

                Ok(IRNode::Index {
                    expr: Box::new(expr_ir),
                    index: Box::new(index_ir),
                })
            }
            Expression::Tuple { elements } => {
                let elements_ir: Vec<_> = elements
                    .iter()
                    .map(|e| self.expression_to_ir(e))
                    .collect::<Result<Vec<_>, _>>()?;

                Ok(IRNode::Tuple {
                    elements: elements_ir,
                })
            }
        }
    }

    /// 리터럴을 IR로 변환합니다
    pub fn literal_to_ir(&self, lit: &Literal) -> Result<IRNode, CodeGenError> {
        match lit {
            Literal::Integer(n) => Ok(IRNode::IntLiteral(*n)),
            Literal::Float(n) => Ok(IRNode::FloatLiteral(*n)),
            Literal::String(s) => Ok(IRNode::StringLiteral(s.clone())),
            Literal::Boolean(b) => Ok(IRNode::BoolLiteral(*b)),
        }
    }

    /// IR을 의사 코드(pseudocode)로 변환합니다
    pub fn ir_to_pseudocode(&self, ir: &IRProgram) -> Result<String, CodeGenError> {
        let mut code = String::new();

        // 함수들의 의사 코드 생성
        for func in &ir.functions {
            code.push_str(&format!("fn {}(", func.name));

            for (i, (param_name, param_type)) in func.params.iter().enumerate() {
                if i > 0 {
                    code.push_str(", ");
                }
                code.push_str(&format!("{}: {}", param_name, param_type));
            }

            code.push_str(&format!(") -> {} {{\n", func.return_type));

            for node in &func.body {
                code.push_str(&format!("  {}\n", self.ir_node_to_pseudocode(node, 2)));
            }

            code.push_str("}\n\n");
        }

        Ok(code)
    }

    /// IR 노드를 의사 코드로 변환합니다 (들여쓰기 포함)
    fn ir_node_to_pseudocode(&self, node: &IRNode, indent: usize) -> String {
        let indent_str = " ".repeat(indent);

        match node {
            IRNode::IntLiteral(n) => format!("{}", n),
            IRNode::FloatLiteral(n) => format!("{}", n),
            IRNode::StringLiteral(s) => format!("\"{}\"", s),
            IRNode::BoolLiteral(b) => format!("{}", b),
            IRNode::Variable(name) => format!("{}", name),
            IRNode::BinaryOp { op, left, right } => {
                format!(
                    "({} {} {})",
                    self.ir_node_to_pseudocode(left, 0),
                    op,
                    self.ir_node_to_pseudocode(right, 0)
                )
            }
            IRNode::UnaryOp { op, operand } => {
                format!("({} {})", op, self.ir_node_to_pseudocode(operand, 0))
            }
            IRNode::If {
                condition,
                then_block,
                else_block,
            } => {
                let mut result = format!(
                    "if ({}) {{\n",
                    self.ir_node_to_pseudocode(condition, 0)
                );

                for stmt in then_block {
                    result.push_str(&format!(
                        "{}  {}\n",
                        indent_str,
                        self.ir_node_to_pseudocode(stmt, indent + 2)
                    ));
                }

                result.push_str(&format!("{}}}", indent_str));

                if let Some(else_stmts) = else_block {
                    result.push_str(" else {\n");
                    for stmt in else_stmts {
                        result.push_str(&format!(
                            "{}  {}\n",
                            indent_str,
                            self.ir_node_to_pseudocode(stmt, indent + 2)
                        ));
                    }
                    result.push_str(&format!("{}}}", indent_str));
                }

                result
            }
            IRNode::FunctionCall { name, args } => {
                let args_str = args
                    .iter()
                    .map(|arg| self.ir_node_to_pseudocode(arg, 0))
                    .collect::<Vec<_>>()
                    .join(", ");

                format!("{}({})", name, args_str)
            }
            IRNode::Array { elements } => {
                let elements_str = elements
                    .iter()
                    .map(|e| self.ir_node_to_pseudocode(e, 0))
                    .collect::<Vec<_>>()
                    .join(", ");

                format!("[{}]", elements_str)
            }
            IRNode::Index { expr, index } => {
                format!(
                    "{}[{}]",
                    self.ir_node_to_pseudocode(expr, 0),
                    self.ir_node_to_pseudocode(index, 0)
                )
            }
            IRNode::Tuple { elements } => {
                let elements_str = elements
                    .iter()
                    .map(|e| self.ir_node_to_pseudocode(e, 0))
                    .collect::<Vec<_>>()
                    .join(", ");

                format!("({})", elements_str)
            }
            IRNode::Assign { name, value } => {
                format!("let {} = {}", name, self.ir_node_to_pseudocode(value, 0))
            }
            IRNode::Return(expr) => {
                format!("return {}", self.ir_node_to_pseudocode(expr, 0))
            }
            IRNode::Block(nodes) => {
                let mut result = String::from("{\n");
                for node in nodes {
                    result.push_str(&format!(
                        "{}  {}\n",
                        indent_str,
                        self.ir_node_to_pseudocode(node, indent + 2)
                    ));
                }
                result.push_str(&format!("{}}}", indent_str));
                result
            }
        }
    }
}

impl Default for CodeGenerator {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_codegen_integer_literal() {
        let mut codegen = CodeGenerator::new();
        let expr = Expression::Literal(Literal::Integer(42));
        let ir = codegen.expression_to_ir(&expr).unwrap();
        assert_eq!(ir, IRNode::IntLiteral(42));
    }

    #[test]
    fn test_codegen_string_literal() {
        let mut codegen = CodeGenerator::new();
        let expr = Expression::Literal(Literal::String("hello".to_string()));
        let ir = codegen.expression_to_ir(&expr).unwrap();
        assert_eq!(ir, IRNode::StringLiteral("hello".to_string()));
    }

    #[test]
    fn test_codegen_variable() {
        let mut codegen = CodeGenerator::new();
        let expr = Expression::Variable("x".to_string());
        let ir = codegen.expression_to_ir(&expr).unwrap();
        assert_eq!(ir, IRNode::Variable("x".to_string()));
    }

    #[test]
    fn test_codegen_binary_operation() {
        let mut codegen = CodeGenerator::new();
        let expr = Expression::BinaryOp {
            op: "Plus".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::Integer(2))),
        };

        let ir = codegen.expression_to_ir(&expr).unwrap();
        match ir {
            IRNode::BinaryOp { op, .. } => {
                assert_eq!(op, "Plus");
            }
            _ => panic!("Expected BinaryOp"),
        }
    }

    #[test]
    fn test_codegen_array_literal() {
        let mut codegen = CodeGenerator::new();
        let expr = Expression::Array {
            elements: vec![
                Expression::Literal(Literal::Integer(1)),
                Expression::Literal(Literal::Integer(2)),
            ],
        };

        let ir = codegen.expression_to_ir(&expr).unwrap();
        match ir {
            IRNode::Array { elements } => {
                assert_eq!(elements.len(), 2);
            }
            _ => panic!("Expected Array"),
        }
    }

    #[test]
    fn test_codegen_let_binding() {
        let mut codegen = CodeGenerator::new();
        let stmt = Statement::LetBinding {
            name: "x".to_string(),
            value: Box::new(Expression::Literal(Literal::Integer(42))),
        };

        let ir = codegen.statement_to_ir(&stmt).unwrap();
        match ir {
            IRNode::Assign { name, .. } => {
                assert_eq!(name, "x");
            }
            _ => panic!("Expected Assign"),
        }
    }

    #[test]
    fn test_codegen_if_statement() {
        let mut codegen = CodeGenerator::new();
        let stmt = Statement::If {
            condition: Box::new(Expression::Literal(Literal::Boolean(true))),
            then_branch: vec![Statement::Expression(Box::new(
                Expression::Literal(Literal::Integer(1)),
            ))],
            else_branch: None,
        };

        let ir = codegen.statement_to_ir(&stmt).unwrap();
        match ir {
            IRNode::If { .. } => {
                // 성공
            }
            _ => panic!("Expected If"),
        }
    }

    #[test]
    fn test_codegen_function_call() {
        let mut codegen = CodeGenerator::new();
        let expr = Expression::FunctionCall {
            name: "add".to_string(),
            args: vec![
                Expression::Literal(Literal::Integer(1)),
                Expression::Literal(Literal::Integer(2)),
            ],
        };

        let ir = codegen.expression_to_ir(&expr).unwrap();
        match ir {
            IRNode::FunctionCall { name, args } => {
                assert_eq!(name, "add");
                assert_eq!(args.len(), 2);
            }
            _ => panic!("Expected FunctionCall"),
        }
    }
}

