// 코드 생성기
// Phase 4: 코드 생성 (AST → IR → Code)

use crate::ast::*;
use crate::ir::*;
use crate::types::Type;
use crate::CompileError;
use std::collections::HashMap;

/// 코드 생성기
pub struct CodeGenerator {
    indent_level: usize,
    current_label: usize,
    function_map: HashMap<String, IRFunction>,
}

impl CodeGenerator {
    /// 새로운 코드 생성기를 생성합니다
    pub fn new() -> Self {
        CodeGenerator {
            indent_level: 0,
            current_label: 0,
            function_map: HashMap::new(),
        }
    }

    /// 프로그램을 생성합니다 (기존 호환성 유지)
    pub fn generate(&self, program: &Program) -> Result<String, CompileError> {
        let mut output = String::new();
        output.push_str("// FV-Lang compiled output\n\n");

        for def in &program.definitions {
            match def {
                Definition::Function { name, params, body } => {
                    output.push_str(&format!("fn {}(", name));
                    for (i, param) in params.iter().enumerate() {
                        if i > 0 {
                            output.push_str(", ");
                        }
                        output.push_str(&format!("{}: unknown", param));
                    }
                    output.push_str(") -> unknown {\n");

                    for stmt in body {
                        output.push_str(&self.generate_statement(stmt)?);
                    }

                    output.push_str("}\n\n");
                }
                Definition::TypeDef { name } => {
                    output.push_str(&format!("type {};\n", name));
                }
            }
        }

        Ok(output)
    }

    /// 프로그램을 IR로 변환합니다
    pub fn ast_to_ir(&mut self, program: &Program) -> Result<IRProgram, CompileError> {
        let mut functions = Vec::new();

        // 함수 정의 처리
        for definition in &program.definitions {
            match definition {
                Definition::Function { name, params, body } => {
                    let ir_body: Vec<_> = body
                        .iter()
                        .map(|stmt| self.statement_to_ir(stmt))
                        .collect::<Result<Vec<_>, _>>()?;

                    let ir_func = IRFunction {
                        name: name.clone(),
                        params: params
                            .iter()
                            .map(|p| (p.clone(), Type::Unknown))
                            .collect(),
                        return_type: Type::Unknown,
                        body: ir_body,
                    };

                    self.function_map.insert(name.clone(), ir_func.clone());
                    functions.push(ir_func);
                }
                Definition::TypeDef { .. } => {
                    // 타입 정의는 현재 처리하지 않음
                }
            }
        }

        Ok(IRProgram {
            functions,
            main: vec![],
        })
    }

    /// 문장을 IR로 변환합니다
    pub fn statement_to_ir(&mut self, stmt: &Statement) -> Result<IRNode, CompileError> {
        match stmt {
            Statement::LetBinding { name, value } => {
                let value_ir = self.expression_to_ir(value)?;
                Ok(IRNode::Assign {
                    name: name.clone(),
                    value: Box::new(value_ir),
                })
            }
            Statement::Return(expr) => {
                let expr_ir = self.expression_to_ir(expr)?;
                Ok(IRNode::Return(Box::new(expr_ir)))
            }
            Statement::If {
                condition,
                then_branch,
                else_branch,
            } => {
                let condition_ir = self.expression_to_ir(condition)?;
                let then_ir: Vec<_> = then_branch
                    .iter()
                    .map(|stmt| self.statement_to_ir(stmt))
                    .collect::<Result<Vec<_>, _>>()?;

                let else_ir = else_branch
                    .as_ref()
                    .map(|stmts| {
                        stmts
                            .iter()
                            .map(|stmt| self.statement_to_ir(stmt))
                            .collect::<Result<Vec<_>, _>>()
                    })
                    .transpose()?;

                Ok(IRNode::If {
                    condition: Box::new(condition_ir),
                    then_block: then_ir,
                    else_block: else_ir,
                })
            }
            Statement::Expression(expr) => self.expression_to_ir(expr),
        }
    }

    /// 표현식을 IR로 변환합니다
    pub fn expression_to_ir(&mut self, expr: &Expression) -> Result<IRNode, CompileError> {
        match expr {
            Expression::Literal(lit) => self.literal_to_ir(lit),
            Expression::Variable(name) => Ok(IRNode::Variable(name.clone())),
            Expression::BinaryOp { op, left, right } => {
                let left_ir = self.expression_to_ir(left)?;
                let right_ir = self.expression_to_ir(right)?;

                Ok(IRNode::BinaryOp {
                    op: op.clone(),
                    left: Box::new(left_ir),
                    right: Box::new(right_ir),
                })
            }
            Expression::UnaryOp { op, operand } => {
                let operand_ir = self.expression_to_ir(operand)?;

                Ok(IRNode::UnaryOp {
                    op: op.clone(),
                    operand: Box::new(operand_ir),
                })
            }
            Expression::FunctionCall { name, args } => {
                let args_ir: Vec<_> = args
                    .iter()
                    .map(|arg| self.expression_to_ir(arg))
                    .collect::<Result<Vec<_>, _>>()?;

                Ok(IRNode::FunctionCall {
                    name: name.clone(),
                    args: args_ir,
                })
            }
            Expression::IfExpr {
                condition,
                then_expr,
                else_expr,
            } => {
                let condition_ir = self.expression_to_ir(condition)?;
                let then_ir = self.expression_to_ir(then_expr)?;
                let else_ir = else_expr
                    .as_ref()
                    .map(|e| self.expression_to_ir(e))
                    .transpose()?;

                Ok(IRNode::If {
                    condition: Box::new(condition_ir),
                    then_block: vec![then_ir],
                    else_block: else_ir.map(|e| vec![e]),
                })
            }
            Expression::Match { .. } => {
                Err(CompileError::GenerationError(
                    "Match 표현식은 아직 구현되지 않았습니다".to_string(),
                ))
            }
            Expression::Array { elements } => {
                let elements_ir: Vec<_> = elements
                    .iter()
                    .map(|e| self.expression_to_ir(e))
                    .collect::<Result<Vec<_>, _>>()?;

                Ok(IRNode::Array {
                    elements: elements_ir,
                })
            }
            Expression::Index { expr, index } => {
                let expr_ir = self.expression_to_ir(expr)?;
                let index_ir = self.expression_to_ir(index)?;

                Ok(IRNode::Index {
                    expr: Box::new(expr_ir),
                    index: Box::new(index_ir),
                })
            }
            Expression::Tuple { elements } => {
                let elements_ir: Vec<_> = elements
                    .iter()
                    .map(|e| self.expression_to_ir(e))
                    .collect::<Result<Vec<_>, _>>()?;

                Ok(IRNode::Tuple {
                    elements: elements_ir,
                })
            }
        }
    }

    /// 리터럴을 IR로 변환합니다
    pub fn literal_to_ir(&self, lit: &Literal) -> Result<IRNode, CompileError> {
        match lit {
            Literal::Integer(n) => Ok(IRNode::IntLiteral(*n)),
            Literal::Float(n) => Ok(IRNode::FloatLiteral(*n)),
            Literal::String(s) => Ok(IRNode::StringLiteral(s.clone())),
            Literal::Boolean(b) => Ok(IRNode::BoolLiteral(*b)),
        }
    }

    /// 기존 코드 생성 (호환성)
    fn generate_statement(&self, stmt: &Statement) -> Result<String, CompileError> {
        let indent = "  ".repeat(self.indent_level + 1);
        match stmt {
            Statement::LetBinding { name, value } => {
                let expr = self.generate_expression(value)?;
                Ok(format!("{}let {} = {};\n", indent, name, expr))
            }
            Statement::Return(expr) => {
                let expr = self.generate_expression(expr)?;
                Ok(format!("{}return {};\n", indent, expr))
            }
            Statement::If {
                condition,
                then_branch,
                else_branch,
            } => {
                let cond = self.generate_expression(condition)?;
                let mut output = format!("{}if {} {{\n", indent, cond);

                for stmt in then_branch {
                    output.push_str(&self.generate_statement(stmt)?);
                }

                if let Some(else_stmts) = else_branch {
                    output.push_str(&format!("{}}} else {{\n", indent));
                    for stmt in else_stmts {
                        output.push_str(&self.generate_statement(stmt)?);
                    }
                }

                output.push_str(&format!("{}}}\n", indent));
                Ok(output)
            }
            Statement::Expression(expr) => {
                let expr = self.generate_expression(expr)?;
                Ok(format!("{}{};\n", indent, expr))
            }
        }
    }

    fn generate_expression(&self, expr: &Expression) -> Result<String, CompileError> {
        match expr {
            Expression::Literal(lit) => self.generate_literal(lit),
            Expression::Variable(name) => Ok(name.clone()),
            Expression::BinaryOp { op, left, right } => {
                let left = self.generate_expression(left)?;
                let right = self.generate_expression(right)?;
                Ok(format!("({} {} {})", left, op, right))
            }
            Expression::UnaryOp { op, operand } => {
                let operand = self.generate_expression(operand)?;
                Ok(format!("({} {})", op, operand))
            }
            Expression::FunctionCall { name, args } => {
                let mut output = format!("{}(", name);
                for (i, arg) in args.iter().enumerate() {
                    if i > 0 {
                        output.push_str(", ");
                    }
                    output.push_str(&self.generate_expression(arg)?);
                }
                output.push(')');
                Ok(output)
            }
            Expression::Array { elements } => {
                let mut output = String::from("[");
                for (i, elem) in elements.iter().enumerate() {
                    if i > 0 {
                        output.push_str(", ");
                    }
                    output.push_str(&self.generate_expression(elem)?);
                }
                output.push(']');
                Ok(output)
            }
            Expression::Index { expr, index } => {
                let expr_str = self.generate_expression(expr)?;
                let index_str = self.generate_expression(index)?;
                Ok(format!("{}[{}]", expr_str, index_str))
            }
            Expression::Tuple { elements } => {
                let mut output = String::from("(");
                for (i, elem) in elements.iter().enumerate() {
                    if i > 0 {
                        output.push_str(", ");
                    }
                    output.push_str(&self.generate_expression(elem)?);
                }
                output.push(')');
                Ok(output)
            }
            Expression::IfExpr {
                condition,
                then_expr,
                else_expr,
            } => {
                let cond = self.generate_expression(condition)?;
                let then_e = self.generate_expression(then_expr)?;
                if let Some(else_e) = else_expr {
                    let else_e = self.generate_expression(else_e)?;
                    Ok(format!("if {} {{ {} }} else {{ {} }}", cond, then_e, else_e))
                } else {
                    Ok(format!("if {} {{ {} }}", cond, then_e))
                }
            }
            Expression::Match { .. } => Err(CompileError::GenerationError(
                "Match는 아직 지원하지 않습니다".to_string(),
            )),
        }
    }

    fn generate_literal(&self, lit: &Literal) -> Result<String, CompileError> {
        Ok(match lit {
            Literal::Integer(n) => n.to_string(),
            Literal::Float(f) => f.to_string(),
            Literal::String(s) => format!("\"{}\"", s),
            Literal::Boolean(b) => b.to_string(),
        })
    }
}

impl Default for CodeGenerator {
    fn default() -> Self {
        Self::new()
    }
}

