// Phase 4 Stage 1: 코드 생성 테스트
// AST to IR 변환 테스트

use fv_lang::ast::*;
use fv_lang::codegen::CodeGenerator;

// ============================================================================
// Stage 1: 코드 생성 (AST → IR) 테스트
// ============================================================================

#[test]
fn test_codegen_integer_literal() {
    let mut gen = CodeGenerator::new();
    let expr = Expression::Literal(Literal::Integer(42));
    let ir = gen.expression_to_ir(&expr).unwrap();
    assert_eq!(ir.to_string(), "42");
}

#[test]
fn test_codegen_float_literal() {
    let mut gen = CodeGenerator::new();
    let expr = Expression::Literal(Literal::Float(3.14));
    let ir = gen.expression_to_ir(&expr).unwrap();
    assert_eq!(ir.to_string(), "3.14");
}

#[test]
fn test_codegen_string_literal() {
    let mut gen = CodeGenerator::new();
    let expr = Expression::Literal(Literal::String("hello".to_string()));
    let ir = gen.expression_to_ir(&expr).unwrap();
    assert_eq!(ir.to_string(), "\"hello\"");
}

#[test]
fn test_codegen_boolean_literal() {
    let mut gen = CodeGenerator::new();
    let expr = Expression::Literal(Literal::Boolean(true));
    let ir = gen.expression_to_ir(&expr).unwrap();
    assert_eq!(ir.to_string(), "true");
}

#[test]
fn test_codegen_variable() {
    let mut gen = CodeGenerator::new();
    let expr = Expression::Variable("x".to_string());
    let ir = gen.expression_to_ir(&expr).unwrap();
    assert_eq!(ir.to_string(), "x");
}

#[test]
fn test_codegen_binary_op_addition() {
    let mut gen = CodeGenerator::new();
    let expr = Expression::BinaryOp {
        op: "Plus".to_string(),
        left: Box::new(Expression::Literal(Literal::Integer(1))),
        right: Box::new(Expression::Literal(Literal::Integer(2))),
    };

    let ir = gen.expression_to_ir(&expr).unwrap();
    assert_eq!(ir.to_string(), "(1 Plus 2)");
}

#[test]
fn test_codegen_binary_op_multiplication() {
    let mut gen = CodeGenerator::new();
    let expr = Expression::BinaryOp {
        op: "Star".to_string(),
        left: Box::new(Expression::Variable("x".to_string())),
        right: Box::new(Expression::Variable("y".to_string())),
    };

    let ir = gen.expression_to_ir(&expr).unwrap();
    assert_eq!(ir.to_string(), "(x Star y)");
}

#[test]
fn test_codegen_unary_op_negation() {
    let mut gen = CodeGenerator::new();
    let expr = Expression::UnaryOp {
        op: "Minus".to_string(),
        operand: Box::new(Expression::Literal(Literal::Integer(5))),
    };

    let ir = gen.expression_to_ir(&expr).unwrap();
    assert_eq!(ir.to_string(), "(Minus 5)");
}

#[test]
fn test_codegen_unary_op_not() {
    let mut gen = CodeGenerator::new();
    let expr = Expression::UnaryOp {
        op: "Not".to_string(),
        operand: Box::new(Expression::Literal(Literal::Boolean(true))),
    };

    let ir = gen.expression_to_ir(&expr).unwrap();
    assert_eq!(ir.to_string(), "(Not true)");
}

#[test]
fn test_codegen_function_call() {
    let mut gen = CodeGenerator::new();
    let expr = Expression::FunctionCall {
        name: "add".to_string(),
        args: vec![
            Expression::Literal(Literal::Integer(1)),
            Expression::Literal(Literal::Integer(2)),
        ],
    };

    let ir = gen.expression_to_ir(&expr).unwrap();
    assert_eq!(ir.to_string(), "add(1, 2)");
}

#[test]
fn test_codegen_array_literal() {
    let mut gen = CodeGenerator::new();
    let expr = Expression::Array {
        elements: vec![
            Expression::Literal(Literal::Integer(10)),
            Expression::Literal(Literal::Integer(20)),
            Expression::Literal(Literal::Integer(30)),
        ],
    };

    let ir = gen.expression_to_ir(&expr).unwrap();
    assert_eq!(ir.to_string(), "[10, 20, 30]");
}

#[test]
fn test_codegen_array_indexing() {
    let mut gen = CodeGenerator::new();
    let expr = Expression::Index {
        expr: Box::new(Expression::Variable("arr".to_string())),
        index: Box::new(Expression::Literal(Literal::Integer(0))),
    };

    let ir = gen.expression_to_ir(&expr).unwrap();
    assert_eq!(ir.to_string(), "arr[0]");
}

#[test]
fn test_codegen_tuple_literal() {
    let mut gen = CodeGenerator::new();
    let expr = Expression::Tuple {
        elements: vec![
            Expression::Literal(Literal::Integer(1)),
            Expression::Literal(Literal::String("a".to_string())),
        ],
    };

    let ir = gen.expression_to_ir(&expr).unwrap();
    assert_eq!(ir.to_string(), "(1, \"a\")");
}

#[test]
fn test_codegen_let_binding() {
    let mut gen = CodeGenerator::new();
    let stmt = Statement::LetBinding {
        name: "x".to_string(),
        value: Box::new(Expression::Literal(Literal::Integer(42))),
    };

    let ir = gen.statement_to_ir(&stmt).unwrap();
    assert_eq!(ir.to_string(), "let x = 42");
}

#[test]
fn test_codegen_return_statement() {
    let mut gen = CodeGenerator::new();
    let stmt = Statement::Return(Box::new(Expression::Literal(Literal::Integer(10))));

    let ir = gen.statement_to_ir(&stmt).unwrap();
    assert_eq!(ir.to_string(), "return 10");
}

#[test]
fn test_codegen_if_statement() {
    let mut gen = CodeGenerator::new();
    let stmt = Statement::If {
        condition: Box::new(Expression::Literal(Literal::Boolean(true))),
        then_branch: vec![Statement::Expression(Box::new(
            Expression::Literal(Literal::Integer(1)),
        ))],
        else_branch: None,
    };

    let ir = gen.statement_to_ir(&stmt).unwrap();
    // IR은 복잡한 구조이므로 타입만 확인
    assert!(ir.to_string().contains("if"));
}

#[test]
fn test_codegen_if_else_statement() {
    let mut gen = CodeGenerator::new();
    let stmt = Statement::If {
        condition: Box::new(Expression::Literal(Literal::Boolean(false))),
        then_branch: vec![Statement::Expression(Box::new(
            Expression::Literal(Literal::Integer(1)),
        ))],
        else_branch: Some(vec![Statement::Expression(Box::new(
            Expression::Literal(Literal::Integer(2)),
        ))]),
    };

    let ir = gen.statement_to_ir(&stmt).unwrap();
    assert!(ir.to_string().contains("if"));
}

#[test]
fn test_codegen_program_with_functions() {
    let mut gen = CodeGenerator::new();
    let program = Program {
        definitions: vec![
            Definition::Function {
                name: "add".to_string(),
                params: vec!["x".to_string(), "y".to_string()],
                body: vec![Statement::Return(Box::new(
                    Expression::BinaryOp {
                        op: "Plus".to_string(),
                        left: Box::new(Expression::Variable("x".to_string())),
                        right: Box::new(Expression::Variable("y".to_string())),
                    },
                ))],
            },
        ],
    };

    let ir = gen.ast_to_ir(&program).unwrap();
    assert_eq!(ir.functions.len(), 1);
    assert_eq!(ir.functions[0].name, "add");
    assert_eq!(ir.functions[0].params.len(), 2);
}

#[test]
fn test_codegen_nested_expressions() {
    let mut gen = CodeGenerator::new();
    let expr = Expression::BinaryOp {
        op: "Plus".to_string(),
        left: Box::new(Expression::BinaryOp {
            op: "Star".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(2))),
