#[test]
fn test_multiple_functions() {
    let mut gen = CodeGenerator::new();
    let program = Program {
        definitions: vec![
            Definition::Function {
                name: "add".to_string(),
                params: vec!["a".to_string(), "b".to_string()],
                body: vec![Statement::Return(Box::new(
                    Expression::BinaryOp {
                        op: "Plus".to_string(),
                        left: Box::new(Expression::Variable("a".to_string())),
                        right: Box::new(Expression::Variable("b".to_string())),
                    },
                ))],
            },
            Definition::Function {
                name: "subtract".to_string(),
                params: vec!["a".to_string(), "b".to_string()],
                body: vec![Statement::Return(Box::new(
                    Expression::BinaryOp {
                        op: "Minus".to_string(),
                        left: Box::new(Expression::Variable("a".to_string())),
                        right: Box::new(Expression::Variable("b".to_string())),
                    },
                ))],
            },
        ],
    };

    let ir = gen.ast_to_ir(&program).unwrap();
    assert_eq!(ir.functions.len(), 2);
    assert_eq!(ir.functions[0].name, "add");
    assert_eq!(ir.functions[1].name, "subtract");
}

